using Microsoft.AspNetCore.Mvc;
using PackCall.Api.Controllers;
using PackCall.Api.Models;
using PackCall.Core.Entities;
using PackCall.Core.Services;

namespace PackCall.Core.Test;

public class ApiControllerTests
{
    private readonly FakeDeliveryRepository _deliveries = new();
    private readonly FakeRecipientRepository _recipients = new();
    private readonly ICampaignService _service;

    public ApiControllerTests()
    {
        _service = new CampaignService(new FakeCampaignRepository(_deliveries), _deliveries, _recipients);
    }

    [Fact]
    public async Task CreateRecipient_ReturnsCreatedResourceAndIncludesItInNewCampaign()
    {
        var recipients = new RecipientsController(_service);
        var created = await recipients.CreateRecipient(
            new CreateRecipientRequest { Email = " User@Example.com " }, CancellationToken.None);

        var result = Assert.IsType<CreatedAtActionResult>(created.Result);
        var recipient = Assert.IsType<RecipientResponse>(result.Value);
        Assert.Equal(nameof(RecipientsController.GetRecipient), result.ActionName);
        Assert.Equal(recipient.Id, result.RouteValues!["id"]);
        Assert.Equal("user@example.com", recipient.Email);

        var campaignId = await _service.CreateCampaignAsync("Кампания", "Текст", CancellationToken.None);
        var delivery = Assert.Single(_deliveries.Items);
        Assert.Equal(campaignId, delivery.CampaignId);
        Assert.Equal(recipient.Id, delivery.RecipientId);
        Assert.Equal(recipient.Email, delivery.RecipientEmail);
    }

    [Fact]
    public async Task CampaignEndpoints_CreateReadAndPatchPreserveOtherField()
    {
        _recipients.Items.Add(new Recipient { Id = Guid.NewGuid(), Email = "user@example.com" });
        var controller = new CampaignsController(_service);

        var created = await controller.CreateCampaign(
            new CreateCampaignRequest { Name = "Название", MessageText = "Текст" }, CancellationToken.None);
        var result = Assert.IsType<CreatedAtActionResult>(created.Result);
        var campaign = Assert.IsType<CampaignResponse>(result.Value);
        Assert.Equal(nameof(CampaignsController.GetCampaign), result.ActionName);
        Assert.Equal(campaign.Id, result.RouteValues!["id"]);

        var detail = await controller.GetCampaign(campaign.Id, CancellationToken.None);
        var response = Assert.IsType<CampaignDetailsResponse>(Assert.IsType<OkObjectResult>(detail.Result).Value);
        Assert.Equal(1, response.Deliveries.Total);
        Assert.Equal(1, response.Deliveries.Waiting);

        var patched = await controller.UpdateCampaign(campaign.Id,
            new UpdateCampaignRequest { Name = "Новое название" }, CancellationToken.None);
        var updated = Assert.IsType<CampaignResponse>(Assert.IsType<OkObjectResult>(patched.Result).Value);
        Assert.Equal("Новое название", updated.Name);
        Assert.Equal("Текст", updated.MessageText);
    }

    [Fact]
    public async Task ReadEndpoints_ReportMissingResourcesAndPageTotals()
    {
        var campaigns = new CampaignsController(_service);
        var deliveries = new DeliveriesController(_service);
        var recipients = new RecipientsController(_service);

        Assert.IsType<NotFoundResult>((await campaigns.GetCampaign(Guid.NewGuid(), CancellationToken.None)).Result);
        Assert.IsType<NotFoundResult>((await deliveries.GetDelivery(Guid.NewGuid(), CancellationToken.None)).Result);
        Assert.IsType<NotFoundResult>((await recipients.GetRecipient(Guid.NewGuid(), CancellationToken.None)).Result);

        _recipients.Items.AddRange(Enumerable.Range(0, 3)
            .Select(index => new Recipient { Id = Guid.NewGuid(), Email = $"user{index}@example.com" }));
        var page = await recipients.GetRecipients(2, 2, CancellationToken.None);
        var response = Assert.IsType<PageResponse<RecipientResponse>>(
            Assert.IsType<OkObjectResult>(page.Result).Value);
        Assert.Single(response.Items);
        Assert.Equal(3, response.TotalCount);
        Assert.Equal(2, response.TotalPages);
    }
}

using System.Net;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Hosting.Server;
using Microsoft.AspNetCore.Hosting.Server.Features;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Storage;
using Microsoft.Extensions.DependencyInjection;
using Npgsql;
using PackCall.Api.Controllers;
using PackCall.Core.Entities;
using PackCall.Core.Repositorys;
using PackCall.Core.Sending;
using PackCall.Core.Services;
using PackCall.Infrastructure;
using Serilog;

namespace PackCall.Core.Test;

// Set PACKCALL_TEST_POSTGRES to a test PostgreSQL connection string.
// Every test creates and removes its own schema; existing tables are never modified.
[Collection("Measurement")]
public partial class CampaignPausePostgresTests : IAsyncLifetime
{
    private readonly string _schema = "packcall_pause_test_" + Guid.NewGuid().ToString("N");
    private readonly FakeMessageSender _sender = new();
    private ServiceProvider? _provider;
    private string _connectionString = "";
    private bool _schemaCreated;

    public async Task InitializeAsync()
    {
        var connectionString = Environment.GetEnvironmentVariable("PACKCALL_TEST_POSTGRES")!;
        await using var connection = new NpgsqlConnection(connectionString);
        await connection.OpenAsync();
        await using var command = new NpgsqlCommand($"CREATE SCHEMA \"{_schema}\"", connection);
        await command.ExecuteNonQueryAsync();
        _schemaCreated = true;
        _connectionString = new NpgsqlConnectionStringBuilder(connectionString) { SearchPath = _schema }.ConnectionString;

        var services = new ServiceCollection();
        AddServices(services);
        _provider = services.BuildServiceProvider();
        await using var context = await _provider.GetRequiredService<IDbContextFactory<AppDbContext>>().CreateDbContextAsync();
        await context.GetService<IRelationalDatabaseCreator>().CreateTablesAsync();
    }

    public async Task DisposeAsync()
    {
        if (_provider is not null)
            await _provider.DisposeAsync();
        if (_schemaCreated)
        {
            await using var connection = new NpgsqlConnection(Environment.GetEnvironmentVariable("PACKCALL_TEST_POSTGRES"));
            await connection.OpenAsync();
            await using var command = new NpgsqlCommand($"DROP SCHEMA \"{_schema}\" CASCADE", connection);
            await command.ExecuteNonQueryAsync();
        }
    }

    private void AddServices(IServiceCollection services)
    {
        services.AddInfrastructure(_connectionString, new PackCall.Infrastructure.Hosting.TestOperatorSettings(PackCall.Infrastructure.Hosting.TestSenderMode.Inprocess, false));
        services.AddSingleton<IMessageSender>(_sender);
        services.AddScoped<ICampaignService, CampaignService>();
        services.AddScoped<IDeliveryProcessingService, DeliveryProcessingService>();
    }

    private async Task<Guid> CreateStartedCampaignAsync(int recipients = 1)
    {
        await using var scope = _provider!.CreateAsyncScope();
        var service = scope.ServiceProvider.GetRequiredService<ICampaignService>();
        for (var i = 0; i < recipients; i++)
            await service.CreateRecipientAsync($"user{i}@example.com", CancellationToken.None);
        var id = await service.CreateCampaignAsync("Рассылка", "Сообщение", CancellationToken.None);
        await service.StartCampaignAsync(id, CancellationToken.None);
        return id;
    }

    [PostgresFact]
    public async Task PauseDuringBatch_AllowsCurrentSendReleasesTailAndResumesWithoutDuplicates()
    {
        var id = await CreateStartedCampaignAsync(4);
        await using var workerScope = _provider!.CreateAsyncScope();
        var processing = workerScope.ServiceProvider.GetRequiredService<IDeliveryProcessingService>();
        var campaigns = workerScope.ServiceProvider.GetRequiredService<ICampaignService>();
        var startedAt = (await campaigns.GetCampaignAsync(id, CancellationToken.None))!.StartedAt;
        var batch = await processing.CaptureBatchAsync(3, "worker-1", TimeSpan.FromSeconds(90), CancellationToken.None);
        Assert.Equal(3, batch.Count);

        var sending = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var acknowledgement = new TaskCompletionSource<SendResult>(TaskCreationOptions.RunContinuationsAsynchronously);
        _sender.AsyncHandler = (_, _) =>
        {
            sending.TrySetResult();
            return acknowledgement.Task;
        };
        var inFlight = processing.ProcessAsync(batch[0], CancellationToken.None);
        await sending.Task.WaitAsync(TimeSpan.FromSeconds(5));
        await using (var pauseScope = _provider!.CreateAsyncScope())
            await pauseScope.ServiceProvider.GetRequiredService<ICampaignService>().PauseCampaignAsync(id, CancellationToken.None);
        acknowledgement.SetResult(SendResult.Success());
        await inFlight.WaitAsync(TimeSpan.FromSeconds(5));
        foreach (var delivery in batch.Skip(1))
            await processing.ProcessAsync(delivery, CancellationToken.None);

        foreach (var tail in batch.Skip(1))
        {
            var stored = await ReadDelivery(tail.Id);
            Assert.Equal(DeliveryStatus.Waiting, stored.DeliveryStatus);
            Assert.Null(stored.WorkerId);
            Assert.Null(stored.LockExpiresAt);
        }
        Assert.Single(_sender.Requests);
        Assert.Equal(CampaignStatus.Paused, (await campaigns.GetCampaignAsync(id, CancellationToken.None))!.Status);
        var counts = await campaigns.GetDeliveryStatusCountsAsync(id, CancellationToken.None);
        Assert.Equal(1, counts.Sent);
        Assert.Equal(3, counts.Waiting);
        Assert.Equal(0, counts.InProgress);
        Assert.Empty(await processing.CaptureBatchAsync(10, "worker-2", TimeSpan.FromSeconds(90), CancellationToken.None));

        await using (var resumeScope = _provider!.CreateAsyncScope())
            await resumeScope.ServiceProvider.GetRequiredService<ICampaignService>().ResumeCampaignAsync(id, CancellationToken.None);
        _sender.AsyncHandler = null;
        var remaining = await processing.CaptureBatchAsync(10, "worker-2", TimeSpan.FromSeconds(90), CancellationToken.None);
        Assert.Equal(3, remaining.Count);
        foreach (var delivery in remaining)
            await processing.ProcessAsync(delivery, CancellationToken.None);

        var completed = (await campaigns.GetCampaignAsync(id, CancellationToken.None))!;
        Assert.Equal(CampaignStatus.Completed, completed.Status);
        Assert.Equal(startedAt, completed.StartedAt);
        Assert.Equal(4, _sender.Requests.Count);
        Assert.Equal(4, _sender.Requests.Select(request => request.DeliveryId).Distinct().Count());
    }

    [PostgresFact]
    public async Task PauseOnLastDelivery_ResumeCompletesWithoutSendingAgain()
    {
        var id = await CreateStartedCampaignAsync();
        await using var scope = _provider!.CreateAsyncScope();
        var processing = scope.ServiceProvider.GetRequiredService<IDeliveryProcessingService>();
        var campaigns = scope.ServiceProvider.GetRequiredService<ICampaignService>();
        var startedAt = (await campaigns.GetCampaignAsync(id, CancellationToken.None))!.StartedAt;
        var delivery = Assert.Single(await processing.CaptureBatchAsync(1, "worker-A", TimeSpan.FromMinutes(2), CancellationToken.None));
        var sending = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var release = new TaskCompletionSource<SendResult>(TaskCreationOptions.RunContinuationsAsynchronously);
        _sender.AsyncHandler = (_, _) => { sending.TrySetResult(); return release.Task; };
        var operation = processing.ProcessAsync(delivery, CancellationToken.None);
        await sending.Task.WaitAsync(Timeout);
        await using var other = _provider!.CreateAsyncScope();
        var control = other.ServiceProvider.GetRequiredService<ICampaignService>();
        await control.PauseCampaignAsync(id, CancellationToken.None);
        release.SetResult(SendResult.Success());
        await operation.WaitAsync(Timeout);
        Assert.Equal(CampaignStatus.Paused, (await control.GetCampaignAsync(id, CancellationToken.None))!.Status);
        Assert.Equal(DeliveryStatus.Sent, (await ReadDelivery(delivery.Id)).DeliveryStatus);
        await control.ResumeCampaignAsync(id, CancellationToken.None);
        var final = (await control.GetCampaignAsync(id, CancellationToken.None))!;
        Assert.Equal(CampaignStatus.Completed, final.Status);
        Assert.Equal(startedAt, final.StartedAt);
        Assert.Single(_sender.Requests);
        Assert.Empty(await processing.CaptureBatchAsync(1, "worker-B", TimeSpan.FromMinutes(2), CancellationToken.None));
    }

    [PostgresFact]
    public async Task StatusUpdates_CannotOverwriteConcurrentPauseOrCompletion()
    {
        var id = await CreateStartedCampaignAsync();
        await using var first = _provider!.CreateAsyncScope();
        await using var second = _provider!.CreateAsyncScope();
        var firstRepository = first.ServiceProvider.GetRequiredService<ICampaingRepository>();
        var secondRepository = second.ServiceProvider.GetRequiredService<ICampaingRepository>();
        var paused = (await firstRepository.Get(id, CancellationToken.None)).Single();
        var completed = (await secondRepository.Get(id, CancellationToken.None)).Single();
        paused.StatusFromInProgressToPaused(DateTime.UtcNow);
        completed.StatusFromInProgressToCompleted(DateTime.UtcNow);

        var results = await Task.WhenAll(
            firstRepository.TryUpdateStatusAsync(paused, CampaignStatus.InProgress, CancellationToken.None),
            secondRepository.TryUpdateStatusAsync(completed, CampaignStatus.InProgress, CancellationToken.None));

        Assert.Single(results, updated => updated);
        var current = (await firstRepository.Get(id, CancellationToken.None)).Single();
        Assert.Equal(results[0] ? CampaignStatus.Paused : CampaignStatus.Completed, current.Status);
        Assert.False(await firstRepository.TryUpdateStatusAsync(results[0] ? completed : paused,
            CampaignStatus.InProgress, CancellationToken.None));
    }

    [PostgresFact]
    public async Task ReleaseCapture_CannotReleaseNewLeaseEvenForTheSameWorker()
    {
        await CreateStartedCampaignAsync();
        await using var scope = _provider!.CreateAsyncScope();
        var repository = scope.ServiceProvider.GetRequiredService<IDeliveryRepository>();
        var now = DateTime.UtcNow;
        var previous = Assert.Single(await repository.CaptureBatchAsync(1, "worker-1", TimeSpan.FromSeconds(10), CancellationToken.None));
        Assert.Empty(await repository.CaptureBatchAsync(1, "worker-2", TimeSpan.FromSeconds(10), CancellationToken.None));
        Assert.Empty(await repository.ReleaseExpiredLocksAsync(CancellationToken.None));
        var later = now.AddSeconds(11);
        await scope.ServiceProvider.GetRequiredService<AppDbContext>().Database.ExecuteSqlRawAsync(
            "UPDATE deliveries SET lock_expires_at = clock_timestamp() - interval '1 second'");
        Assert.Single(await repository.ReleaseExpiredLocksAsync(CancellationToken.None));
        var current = Assert.Single(await repository.CaptureBatchAsync(1, "worker-1", TimeSpan.FromSeconds(90), CancellationToken.None));

        Assert.Null(await repository.ReleaseCapturedAsync(previous.Id, "worker-1", previous.LockExpiresAt!.Value, later, CancellationToken.None));
        var stored = Assert.Single(await repository.Get(current.Id, CancellationToken.None));
        Assert.Equal(DeliveryStatus.InProgress, stored.DeliveryStatus);
        Assert.Equal(current.LockExpiresAt, stored.LockExpiresAt);

        var released = await repository.ReleaseCapturedAsync(current.Id, "worker-1", current.LockExpiresAt!.Value, later, CancellationToken.None);
        Assert.NotNull(released);
        Assert.Equal(DeliveryStatus.Waiting, released.DeliveryStatus);
        Assert.Null(released.WorkerId);
        Assert.Null(released.LockExpiresAt);
    }

    [PostgresFact]
    public async Task HttpPauseAndResume_ReturnStatesAndRejectInvalidOperations()
    {
        var id = await CreateStartedCampaignAsync();
        var builder = WebApplication.CreateBuilder();
        builder.WebHost.UseUrls("http://127.0.0.1:0");
        AddServices(builder.Services);
        builder.Services.AddSingleton<Serilog.ILogger>(Log.Logger);
        builder.Services.AddControllers().AddApplicationPart(typeof(CampaignsController).Assembly)
            .AddJsonOptions(options => options.JsonSerializerOptions.Converters.Add(new JsonStringEnumConverter()));
        builder.Services.AddProblemDetails();
        // Register the production handler without changing its visibility for tests.
        var handler = typeof(CampaignsController).Assembly.GetType("PackCall.Api.Middleware.ApiExceptionHandler", throwOnError: true)!;
        builder.Services.AddSingleton(typeof(IExceptionHandler), handler);
        await using var app = builder.Build();
        app.UseExceptionHandler();
        app.MapControllers();
        await app.StartAsync();
        var address = app.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>()!.Addresses.Single();
        using var client = new HttpClient { BaseAddress = new Uri(address) };

        using var paused = await client.PostAsync($"/api/campaigns/{id}/pause", null);
        Assert.Equal(HttpStatusCode.OK, paused.StatusCode);
        var pausedBody = await paused.Content.ReadFromJsonAsync<System.Text.Json.JsonElement>();
        Assert.Equal("Paused", pausedBody.GetProperty("status").GetString());
        using var repeatedPause = await client.PostAsync($"/api/campaigns/{id}/pause", null);
        Assert.Equal(HttpStatusCode.OK, repeatedPause.StatusCode);
        var repeatedBody = await repeatedPause.Content.ReadFromJsonAsync<System.Text.Json.JsonElement>();
        Assert.Equal(pausedBody.GetProperty("updatedAt").GetString(), repeatedBody.GetProperty("updatedAt").GetString());
        using var deletePaused = await client.DeleteAsync($"/api/campaigns/{id}");
        Assert.Equal(HttpStatusCode.Conflict, deletePaused.StatusCode);
        using var patchPaused = await client.PatchAsJsonAsync($"/api/campaigns/{id}", new { name = "Другой текст" });
        Assert.Equal(HttpStatusCode.Conflict, patchPaused.StatusCode);

        using var resumed = await client.PostAsync($"/api/campaigns/{id}/resume", null);
        Assert.Equal(HttpStatusCode.OK, resumed.StatusCode);
        var resumedBody = await resumed.Content.ReadFromJsonAsync<System.Text.Json.JsonElement>();
        Assert.Equal("InProgress", resumedBody.GetProperty("status").GetString());
        Assert.Equal(pausedBody.GetProperty("startedAt").GetString(), resumedBody.GetProperty("startedAt").GetString());
        using var repeatedResume = await client.PostAsync($"/api/campaigns/{id}/resume", null);
        Assert.Equal(HttpStatusCode.OK, repeatedResume.StatusCode);
        foreach (var action in new[] { "pause", "resume" })
        {
            using var missing = await client.PostAsync($"/api/campaigns/{Guid.NewGuid()}/{action}", null);
            Assert.Equal(HttpStatusCode.NotFound, missing.StatusCode);
            using var draft = await client.PostAsJsonAsync("/api/campaigns", new { name = "Черновик", messageText = "Текст" });
            draft.EnsureSuccessStatusCode();
            var draftId = (await draft.Content.ReadFromJsonAsync<System.Text.Json.JsonElement>()).GetProperty("id").GetGuid();
            using var invalid = await client.PostAsync($"/api/campaigns/{draftId}/{action}", null);
            Assert.Equal(HttpStatusCode.Conflict, invalid.StatusCode);
        }
    }
}

internal sealed class PostgresFactAttribute : FactAttribute
{
    public PostgresFactAttribute()
    {
        if (string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable("PACKCALL_TEST_POSTGRES")))
            Skip = "Set PACKCALL_TEST_POSTGRES to run against an isolated schema in PostgreSQL.";
    }
}

using PackCall.Core.Entities;
using PackCall.Core.Exceptions;
using PackCall.Core.Services;

namespace PackCall.Core.Test;

public class CampaignServiceTests
{
    private readonly FakeCampaignRepository _campaignRepository;
    private readonly FakeDeliveryRepository _deliveryRepository = new();
    private readonly FakeRecipientRepository _recipientRepository = new();
    private readonly ICampaignService _service;

    public CampaignServiceTests()
    {
        _campaignRepository = new FakeCampaignRepository(_deliveryRepository);
        _service = new CampaignService(_campaignRepository, _deliveryRepository, _recipientRepository);
    }

    private Task<Guid> CreateCampaignAsync() =>
        _service.CreateCampaignAsync("Кампания", "Текст", CancellationToken.None);

    [Theory]
    [InlineData("")]
    [InlineData("invalid-email")]
    [InlineData("Name <user@example.com>")]
    public async Task CreateRecipient_RejectsInvalidEmail(string email)
    {
        await Assert.ThrowsAsync<ArgumentException>(() =>
            _service.CreateRecipientAsync(email, CancellationToken.None));
        Assert.Empty(_recipientRepository.Items);
    }

    [Fact]
    public async Task CreateRecipient_RejectsDuplicateIgnoringCase()
    {
        _recipientRepository.Items.Add(new Recipient { Id = Guid.NewGuid(), Email = "User@Example.com" });

        await Assert.ThrowsAsync<RecipientAlreadyExistsException>(() =>
            _service.CreateRecipientAsync(" user@example.com ", CancellationToken.None));
        Assert.Single(_recipientRepository.Items);
    }

    [Fact]
    public async Task CreateCampaign_PersistsDraftAndOneWaitingDeliveryPerRecipient()
    {
        var recipient = new Recipient { Id = Guid.NewGuid(), Email = "first@example.com" };
        _recipientRepository.Items.Add(recipient);
        _recipientRepository.Items.Add(new Recipient { Id = Guid.NewGuid(), Email = "second@example.com" });

        var id = await CreateCampaignAsync();
        var campaign = await _service.GetCampaignAsync(id, CancellationToken.None);

        Assert.NotNull(campaign);
        Assert.Equal(CampaignStatus.Draft, campaign.Status);
        Assert.Equal(2, _deliveryRepository.Items.Count);
        Assert.All(_deliveryRepository.Items, delivery =>
        {
            Assert.Equal(id, delivery.CampaignId);
            Assert.Equal(DeliveryStatus.Waiting, delivery.DeliveryStatus);
        });
        Assert.Equal(2, _deliveryRepository.Items.Select(delivery => delivery.RecipientId).Distinct().Count());

        recipient.Email = "changed@example.com";
        Assert.Equal("first@example.com", _deliveryRepository.Items.Single(d => d.RecipientId == recipient.Id).RecipientEmail);
    }

    [Fact]
    public async Task CreateCampaign_WithInvalidRecipient_PersistsNothing()
    {
        _recipientRepository.Items.Add(new Recipient { Id = Guid.NewGuid(), Email = "valid@example.com" });
        _recipientRepository.Items.Add(new Recipient { Id = Guid.NewGuid(), Email = " " });

        await Assert.ThrowsAsync<ArgumentException>(() => CreateCampaignAsync());

        Assert.Empty((await _service.GetCampaignsAsync(1, 10, CancellationToken.None)).Items);
        Assert.Empty(_deliveryRepository.Items);
    }

    [Fact]
    public async Task CreateCampaign_FormsDeliveriesInBatchesAndBlocksChangesUntilReady()
    {
        _recipientRepository.Items.AddRange(Enumerable.Range(0, 1001)
            .Select(index => new Recipient { Id = Guid.NewGuid(), Email = $"user{index}@example.com" }));
        var batchSizes = new List<int>();
        _deliveryRepository.BeforeAddBatchAsync = async deliveries =>
        {
            batchSizes.Add(deliveries.Count);
            var campaignId = deliveries[0].CampaignId;
            Assert.Equal(CampaignStatus.Forming,
                (await _service.GetCampaignAsync(campaignId, CancellationToken.None))!.Status);
            await Assert.ThrowsAsync<InvalidStatusTransitionException>(() =>
                _service.StartCampaignAsync(campaignId, CancellationToken.None));
            await Assert.ThrowsAsync<InvalidOperationException>(() =>
                _service.UpdateCampaignAsync(campaignId, "Новое имя", "Новый текст", CancellationToken.None));
        };

        var id = await CreateCampaignAsync();

        Assert.True(batchSizes.Count > 1);
        Assert.Equal(1001, batchSizes.Sum());
        Assert.Equal(1001, _deliveryRepository.Items.Count);
        Assert.Equal(CampaignStatus.Draft, (await _service.GetCampaignAsync(id, CancellationToken.None))!.Status);
        await _service.StartCampaignAsync(id, CancellationToken.None);
        Assert.Equal(CampaignStatus.InProgress, (await _service.GetCampaignAsync(id, CancellationToken.None))!.Status);
    }

    [Fact]
    public async Task CreateCampaign_WhenLaterBatchFails_RemovesPartialCampaign()
    {
        _recipientRepository.Items.AddRange(Enumerable.Range(0, 501)
            .Select(index => new Recipient { Id = Guid.NewGuid(), Email = $"user{index}@example.com" }));
        var batchNumber = 0;
        _deliveryRepository.BeforeAddBatchAsync = _ =>
        {
            if (++batchNumber == 2)
                throw new InvalidOperationException("Ошибка сохранения порции");
            return Task.CompletedTask;
        };

        await Assert.ThrowsAsync<InvalidOperationException>(() => CreateCampaignAsync());

        Assert.Empty((await _service.GetCampaignsAsync(1, 10, CancellationToken.None)).Items);
        Assert.Empty(_deliveryRepository.Items);
    }

    [Fact]
    public async Task CreateCampaign_WhenCancelledAfterFirstBatch_RemovesPartialCampaign()
    {
        _recipientRepository.Items.AddRange(Enumerable.Range(0, 501)
            .Select(index => new Recipient { Id = Guid.NewGuid(), Email = $"user{index}@example.com" }));
        using var cancellation = new CancellationTokenSource();
        _deliveryRepository.BeforeAddBatchAsync = _ =>
        {
            cancellation.Cancel();
            return Task.CompletedTask;
        };

        await Assert.ThrowsAsync<OperationCanceledException>(() =>
            _service.CreateCampaignAsync("Кампания", "Текст", cancellation.Token));

        Assert.Empty((await _service.GetCampaignsAsync(1, 10, CancellationToken.None)).Items);
        Assert.Empty(_deliveryRepository.Items);
    }

    [Fact]
    public async Task StartCampaign_WhenAlreadyStarted_DoesNotChangeDatesOrDeliveries()
    {
        _recipientRepository.Items.Add(new Recipient { Id = Guid.NewGuid(), Email = "user@example.com" });
        var id = await CreateCampaignAsync();
        await _service.StartCampaignAsync(id, CancellationToken.None);
        var campaign = (await _service.GetCampaignAsync(id, CancellationToken.None))!;
        var startedAt = campaign.StartedAt;
        var updatedAt = campaign.UpdatedAt;
        var delivery = _deliveryRepository.Items.Single();
        delivery.SetCapturedForTest("worker-1", DateTime.UtcNow.AddMinutes(2));

        await _service.StartCampaignAsync(id, CancellationToken.None);

        Assert.Equal(startedAt, campaign.StartedAt);
        Assert.Equal(updatedAt, campaign.UpdatedAt);
        Assert.Same(delivery, Assert.Single(_deliveryRepository.Items));
        Assert.Equal(DeliveryStatus.InProgress, delivery.DeliveryStatus);
    }

    [Fact]
    public async Task StartCampaign_WhenCompleted_RejectsRestart()
    {
        var id = await CreateCampaignAsync();
        await _service.StartCampaignAsync(id, CancellationToken.None);
        var campaign = (await _service.GetCampaignAsync(id, CancellationToken.None))!;
        campaign.StatusFromInProgressToCompleted(DateTime.UtcNow);

        await Assert.ThrowsAsync<InvalidStatusTransitionException>(() =>
            _service.StartCampaignAsync(id, CancellationToken.None));

        Assert.Equal(CampaignStatus.Completed, campaign.Status);
    }

    [Fact]
    public async Task DeleteCampaign_InProgress_Throws()
    {
        var id = await CreateCampaignAsync();
