using System.Linq.Expressions;

namespace PackCall.Core.Test;

internal sealed class FakeCampaignRepository : ICampaingRepository
{
    private readonly Dictionary<Guid, Campaign> _store = new();
    private readonly Dictionary<Guid, CampaignStatus> _statuses = new();
    private readonly FakeDeliveryRepository? _deliveries;

    public FakeCampaignRepository(FakeDeliveryRepository? deliveries = null)
    {
        _deliveries = deliveries;
    }

    public int CreateCount { get; private set; }
    public int UpdateCount { get; private set; }
    public Action? OnGet { get; set; }
    public Action? OnTryUpdateStatus { get; set; }

    public Task<IEnumerable<Campaign>> Get(Guid id, CancellationToken ct)
    {
        OnGet?.Invoke();
        return Task.FromResult(_store.TryGetValue(id, out var campaign)
            ? new[] { campaign }.AsEnumerable()
            : Enumerable.Empty<Campaign>());
    }

    public Task<PageResult<Campaign>> GetPage(int pageNumber, int pageSize, CancellationToken ct)
    {
        var items = _store.Values
            .OrderBy(c => c.Id)
            .Skip((pageNumber - 1) * pageSize)
            .Take(pageSize)
            .ToList();
        return Task.FromResult(new PageResult<Campaign>(items, _store.Count));
    }

    public Task<Campaign> Create(Campaign campaign, CancellationToken ct)
    {
        _store[campaign.Id] = campaign;
        _statuses[campaign.Id] = campaign.Status;
        foreach (var delivery in campaign.Deliveries)
            _deliveries?.Add(delivery);
        CreateCount++;
        return Task.FromResult(campaign);
    }

    public Task<Campaign> Update(Campaign campaign, CancellationToken ct)
    {
        if (!_store.ContainsKey(campaign.Id))
            throw new KeyNotFoundException($"Кампания {campaign.Id} не найдена.");
        _store[campaign.Id] = campaign;
        _statuses[campaign.Id] = campaign.Status;
        UpdateCount++;
        return Task.FromResult(campaign);
    }

    public async Task<bool> TryUpdateStatusAsync(Campaign campaign, CampaignStatus expectedStatus, CancellationToken ct)
    {
        OnTryUpdateStatus?.Invoke();
        if (!_statuses.TryGetValue(campaign.Id, out var status) || status != expectedStatus)
            return false;
        await Update(campaign, ct);
        return true;
    }

    public Task<bool> Delete(Guid id, CancellationToken ct)
    {
        if (!_store.Remove(id))
            return Task.FromResult(false);
        _statuses.Remove(id);
        _deliveries?.RemoveByCampaign(id);
        return Task.FromResult(true);
    }
}

internal sealed class FakeRecipientRepository : IRecipientRepository
{
    public List<Recipient> Items { get; } = new();

    public Task<Recipient> CreateAsync(Recipient recipient, CancellationToken ct)
    {
        ct.ThrowIfCancellationRequested();
        if (Items.Any(item => string.Equals(item.Email, recipient.Email, StringComparison.OrdinalIgnoreCase)))
            throw new RecipientAlreadyExistsException();
        Items.Add(recipient);
        return Task.FromResult(recipient);
    }

    public Task<Recipient?> GetByEmailAsync(string email, CancellationToken ct) =>
        Task.FromResult(Items.FirstOrDefault(recipient =>
            string.Equals(recipient.Email, email, StringComparison.OrdinalIgnoreCase)));

    public Task<IReadOnlyList<Recipient>> GetBatchAsync(int offset, int batchSize, CancellationToken ct) =>
        Task.FromResult<IReadOnlyList<Recipient>>(Items.DistinctBy(recipient => recipient.Id)
            .OrderBy(recipient => recipient.Id).Skip(offset).Take(batchSize).ToList());

    public Task<Recipient?> GetAsync(Guid id, CancellationToken ct) =>
        Task.FromResult(Items.FirstOrDefault(recipient => recipient.Id == id));

    public Task<PageResult<Recipient>> GetPageAsync(int pageNumber, int pageSize, CancellationToken ct) =>
        Task.FromResult(new PageResult<Recipient>(
            Items.OrderBy(recipient => recipient.Id).Skip((pageNumber - 1) * pageSize).Take(pageSize).ToList(),
            Items.Count));
}

internal sealed class FakeDeliveryRepository : IDeliveryRepository
{
    private readonly List<Delivery> _store = new();

    public FakeDeliveryRepository()
    {
    }

    public IReadOnlyList<Delivery> Items => _store;

    public Func<IReadOnlyList<Delivery>, Task>? BeforeAddBatchAsync { get; set; }

    public async Task AddBatchAsync(IReadOnlyList<Delivery> deliveries, CancellationToken ct)
    {
        if (BeforeAddBatchAsync is not null)
            await BeforeAddBatchAsync(deliveries);
        _store.AddRange(deliveries);
    }

    public void Add(Delivery delivery) => _store.Add(delivery);

    public void RemoveByCampaign(Guid campaignId) =>
        _store.RemoveAll(delivery => delivery.CampaignId == campaignId);

    public Task<IEnumerable<Delivery>> Get(Guid id, CancellationToken ct) =>
        Task.FromResult(_store.Where(d => d.Id == id).ToList().AsEnumerable());

    public Task<IEnumerable<Delivery>> Get(Guid campaignId, Expression<Func<Delivery, bool>> predicate, CancellationToken ct) =>
        Task.FromResult(_store.AsQueryable().Where(d => d.CampaignId == campaignId).Where(predicate).ToList().AsEnumerable());

    public Task<PageResult<Delivery>> GetPage(Guid campaignId, int pageNumber, int pageSize, CancellationToken ct)
    {
        var deliveries = _store.Where(d => d.CampaignId == campaignId).OrderBy(d => d.Id).ToList();
        var items = deliveries.Skip((pageNumber - 1) * pageSize).Take(pageSize).ToList();
        return Task.FromResult(new PageResult<Delivery>(items, deliveries.Count));
    }

    public Task<DeliveryStatusCounts> GetStatusCountsAsync(Guid campaignId, CancellationToken ct)
    {
        var deliveries = _store.Where(delivery => delivery.CampaignId == campaignId).ToList();
        return Task.FromResult(new DeliveryStatusCounts(deliveries.Count,
            deliveries.Count(delivery => delivery.DeliveryStatus == DeliveryStatus.Waiting),
            deliveries.Count(delivery => delivery.DeliveryStatus == DeliveryStatus.InProgress),
            deliveries.Count(delivery => delivery.DeliveryStatus == DeliveryStatus.Sent),
            deliveries.Count(delivery => delivery.DeliveryStatus == DeliveryStatus.Failed)));
    }

    public Task<IReadOnlyList<Delivery>> CaptureBatchAsync(
        int batchSize, string workerId, TimeSpan lockDuration, CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        var captured = new List<Delivery>();
        foreach (var delivery in _store)
        {
            if (captured.Count >= batchSize)
                break;
            if (delivery.DeliveryStatus != DeliveryStatus.Waiting)
                continue;
            if (delivery.Campaign is not null && delivery.Campaign.Status != CampaignStatus.InProgress)
                continue;

            delivery.SetCapturedForTest(workerId, now + lockDuration, now);
            captured.Add(delivery);
        }

        return Task.FromResult<IReadOnlyList<Delivery>>(captured);
    }

    public Task<IReadOnlyList<Delivery>> ReleaseExpiredLocksAsync(CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        var released = _store.Where(d => d.DeliveryStatus == DeliveryStatus.InProgress &&
            d.LockExpiresAt is not null && d.LockExpiresAt <= now).ToList();
        foreach (var delivery in released)
            delivery.SetWaitingForTest(now);
        return Task.FromResult<IReadOnlyList<Delivery>>(released);
    }

    public Task<Delivery?> ReleaseCapturedAsync(
        Guid deliveryId, string workerId, DateTime lockExpiresAt, DateTime now, CancellationToken ct)
    {
        var delivery = _store.SingleOrDefault(row => row.Id == deliveryId &&
            row.DeliveryStatus == DeliveryStatus.InProgress && row.WorkerId == workerId && row.LockExpiresAt == lockExpiresAt);
        delivery?.SetWaitingForTest(now);
        return Task.FromResult(delivery);
    }

    public Func<Task<bool>>? CompleteHandler { get; set; }
    public int PendingChecks { get; private set; }
    public Task<bool> TryCompleteAsync(Delivery delivery, string? workerId, DateTime? lockExpiresAt, CancellationToken ct) =>
        CompleteHandler?.Invoke() ?? Task.FromResult(workerId is not null && lockExpiresAt > DateTime.UtcNow);


    public Task<bool> HasPendingDeliveriesAsync(Guid campaignId, CancellationToken ct)
    {
        PendingChecks++;
        return Task.FromResult(_store.Any(d => d.CampaignId == campaignId &&
            d.DeliveryStatus is DeliveryStatus.Waiting or DeliveryStatus.InProgress));
    }
}

internal sealed class FakeMessageSender : IMessageSender
{
    public Func<SendRequest, SendResult>? Handler { get; set; }
    public Func<SendRequest, CancellationToken, Task<SendResult>>? AsyncHandler { get; set; }

    public List<SendRequest> Requests { get; } = new();
    public List<bool> SimulateErrors { get; } = new();

    public Task<SendResult> SendAsync(SendRequest request, bool simulateErrors, CancellationToken ct)
    {
        Requests.Add(request);
        SimulateErrors.Add(simulateErrors);
        return AsyncHandler?.Invoke(request, ct) ??
            Task.FromResult(Handler?.Invoke(request) ?? SendResult.Success());
    }
}

internal sealed class FakeJournal : IDeliveryStatusJournal
{
    public List<StatusChangeEntry> Entries { get; } = new();
    public Task AppendAsync(StatusChangeEntry entry, CancellationToken ct)
    {
        Entries.Add(entry);
        return Task.CompletedTask;
    }
}

using System.Diagnostics.Metrics;
using PackCall.Core.Diagnostics;

namespace PackCall.Core.Test;

[CollectionDefinition("Measurement", DisableParallelization = true)]
public sealed class MeasurementCollection;

[Collection("Measurement")]
public sealed class MeasurementCollectorTests
{
    private static MeasurementOptions Options => new() { Enabled = true, SessionId = Guid.NewGuid(), OutputDirectory = "unused" };
    private static readonly SeriesKey Counter = new((int)Event.TerminalApplied, Outcome.Sent, Purpose.None);
    private static readonly SeriesKey Duration = new((int)Operation.OperatorCall, Outcome.Accepted, Purpose.None);

    [Fact]
    public void EffectiveSettingsSerializationIsAnAllowlist()
    {
        // Unrelated configuration is deliberately not an input to the export DTO.
        var configuration = new Dictionary<string, string> { ["Password"] = "secret-canary", ["Parallelism"] = "4" };
        var exported = new EffectiveMeasurementSettings(int.Parse(configuration["Parallelism"]), 10, 90, 15, .25, 5, 5, false, "http");
        var json = System.Text.Json.JsonSerializer.Serialize(exported);
        Assert.DoesNotContain("secret-canary", json);
        Assert.DoesNotContain("Password", json);
        Assert.Throws<ArgumentException>(() => new MeasurementCollector(new() { Enabled = true }));
    }

    [Fact]
    public void DisabledHasNoListenerFilesOrWindowsAndIdentityIsPerStart()
    {
        var directory = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
        using var first = new MeasurementCollector(new() { OutputDirectory = directory });
        using var second = new MeasurementCollector(new());
        PerformanceMetrics.Count(Event.TerminalApplied, Outcome.Sent);
        first.Add(Counter, 10);
        Assert.Null(first.Close());
        Assert.NotEqual(first.InstanceId, second.InstanceId);
        Assert.False(Directory.Exists(directory));
    }

    [Fact]
    public void MonotonicPartialAndEmptyWindowsPreserveTotalsDespiteWallClockJump()
    {
        var clock = new Clock();
        using var collector = new MeasurementCollector(Options, clock);
        collector.Add(Counter, 3);
        collector.Observe(Duration, 0);
        collector.Observe(Duration, 100);
        clock.Tick(2);
        clock.Utc += TimeSpan.FromHours(1);
        var first = collector.Close(true)!;
        Assert.Equal(2, first.DurationSeconds);
        Assert.True(first.ClockJump);
        Assert.True(first.Partial);
        Assert.Equal(new CounterWindow(3, 3), first.Counters[Counter]);
        Assert.Equal(2, first.Histograms[Duration].Count);
        Assert.Equal(100, first.Histograms[Duration].Sum);
        Assert.Equal(1, first.Histograms[Duration].Buckets[0]);
        clock.Tick(10);
        var empty = collector.Close()!;
        Assert.Equal(new CounterWindow(0, 3), empty.Counters[Counter]);
        Assert.Equal(0, empty.Histograms[Duration].Count);
        Assert.Null(empty.Histograms[Duration].Min);
        Assert.Equal(2, empty.ElapsedStartSeconds);
    }

    [Fact]
    public async Task ConcurrentClosingLosesNoEventsOrHistogramSamples()
    {
        using var collector = new MeasurementCollector(Options);
        var windows = new List<MeasurementWindow>();
        var writers = Enumerable.Range(0, 8).Select(_ => Task.Run(() =>
        {
            for (var i = 0; i < 10000; i++) { collector.Add(Counter, 1); collector.Observe(Duration, 2); }
        })).ToArray();
        while (writers.Any(t => !t.IsCompleted)) { windows.Add(collector.Close()!); await Task.Delay(1); }
        await Task.WhenAll(writers);
        windows.Add(collector.Close(true)!);
        Assert.Equal(80000, windows.Sum(w => w.Counters.GetValueOrDefault(Counter)?.Delta ?? 0));
        Assert.Equal(80000, windows.Sum(w => w.Histograms.GetValueOrDefault(Duration)?.Count ?? 0));
        Assert.Equal(160000, windows.Sum(w => w.Histograms.GetValueOrDefault(Duration)?.Sum ?? 0));
        Assert.Equal(80000, windows[^1].Counters[Counter].Cumulative);
        Assert.All(windows, w => Assert.All(w.Histograms.Values, h => Assert.Equal(h.Count, h.Buckets.Sum())));
    }

    [Fact]
    public void ListenerRecordsAndRejectsUnboundedCategories()
    {
        using var collector = new MeasurementCollector(Options);
        PerformanceMetrics.Count(Event.TerminalApplied, Outcome.Sent, 5);
        PerformanceMetrics.Duration(Operation.OperatorCall, Outcome.Accepted, 12);
        PerformanceMetrics.Count((Event)99999);
        var window = collector.Close()!;
        Assert.Equal(2, window.Counters.Count);
        Assert.Equal(5, window.Counters[Counter].Delta);
        Assert.Equal(12, window.Histograms[Duration].Sum);
        for (var i = 0; i < 10000; i++) collector.Observe(new(i, Outcome.Success, Purpose.None), 10);
        window = collector.Close()!;
        Assert.True(window.Histograms.Count + window.Counters.Count <= MeasurementCollector.MaximumSeries);
        Assert.True(window.DroppedMeasurements > 0);
        // One active + one closed copy of all bounded bucket arrays is well below the 16 MiB budget.
        Assert.True(2L * MeasurementCollector.MaximumSeries * (MeasurementCollector.Bounds.Count + 1) * sizeof(long) < 4 * 1024 * 1024);
    }

    [Fact]
    public void ThrowingCallbackCannotChangeBusinessResult()
    {
        using var listener = new MeterListener();
        listener.InstrumentPublished = (instrument, l) =>
        {
            if (instrument.Meter.Name == PerformanceMetrics.MeterName) l.EnableMeasurementEvents(instrument);
        };
        listener.SetMeasurementEventCallback<long>((_, _, _, _) => throw new IOException("secret-canary"));
        listener.SetMeasurementEventCallback<double>((_, _, _, _) => throw new IOException("secret-canary"));
        listener.Start();
        PerformanceMetrics.Count(Event.TerminalApplied);
        PerformanceMetrics.Duration(Operation.ResultPersist, Outcome.Applied, 1);
    }

    private sealed class Clock : TimeProvider
    {
        private long _ticks;
        public DateTimeOffset Utc = DateTimeOffset.UnixEpoch;
        public override long TimestampFrequency => 1000;
        public override long GetTimestamp() => _ticks;
        public override DateTimeOffset GetUtcNow() => Utc;
        public void Tick(int seconds) { _ticks += seconds * 1000; Utc += TimeSpan.FromSeconds(seconds); }
    }
}

using System.Text;
using System.Text.Json;
using PackCall.Core.Diagnostics;
using PackCall.Infrastructure.Hosting;

namespace PackCall.Core.Test;

[Collection("Measurement")]
public sealed class MeasurementWriterTests : IDisposable
{
    private readonly string _root = Path.Combine(Path.GetTempPath(), "packcall-measurement-test-" + Guid.NewGuid());

    [Fact]
    public void BoundedRetainedTelemetryStateFitsSixteenMiB()
    {
        var before = GC.GetTotalMemory(true);
        using var collector = new MeasurementCollector(new() { Enabled = true, SessionId = Guid.NewGuid(), OutputDirectory = _root });
        for (var i = 0; i < MeasurementCollector.MaximumSeries; i++)
            collector.Observe(new(i % 12, (Outcome)((i / 12) % 23), (Purpose)(i / (12 * 23))), 10);
        var closed = collector.Close();
        var writer = new MeasurementFileWriter(_root, collector.InstanceId);
        var runtime = new MeasurementFileWriter(_root, collector.InstanceId, prefix: "runtime", maximumRecordBytes: 65536);
        for (var i = 0; i < 3; i++)
        {
            Assert.True(writer.TryEnqueue(new byte[MeasurementFileWriter.MaximumRecordBytes]));
            Assert.True(runtime.TryEnqueue(new byte[65536]));
        }
        var currentSerialization = new byte[MeasurementFileWriter.MaximumRecordBytes];
        var retained = GC.GetTotalMemory(true) - before;
        Assert.InRange(retained, 0, 16L * 1024 * 1024);
        GC.KeepAlive(closed); GC.KeepAlive(writer); GC.KeepAlive(runtime); GC.KeepAlive(currentSerialization);
    }

    [Fact]
    public async Task QueueIsBoundedAndRotationPreservesEarlyFiles()
    {
        var writer = new MeasurementFileWriter(_root, Guid.NewGuid(), rotationBytes: 10);
        var bytes = Encoding.UTF8.GetBytes("{\"n\":1}");
        Assert.True(writer.TryEnqueue(bytes));
        Assert.True(writer.TryEnqueue(bytes));
        Assert.True(writer.TryEnqueue(bytes));
        Assert.False(writer.TryEnqueue(bytes));
        Assert.Equal(1, writer.Dropped);
        writer.Complete();
        await writer.RunAsync();
        Assert.False(writer.Failed);
        var files = Directory.GetFiles(writer.DirectoryPath, "intervals-*.jsonl");
        Assert.Equal(3, files.Length);
        Assert.All(files, file => Assert.Equal("{\"n\":1}\n", File.ReadAllText(file)));
        using var checksums = JsonDocument.Parse(File.ReadAllText(Path.Combine(writer.DirectoryPath, "checksums.json")));
        Assert.Equal(3, checksums.RootElement.EnumerateObject().Count());
        Assert.False(writer.TryEnqueue(new byte[MeasurementFileWriter.MaximumRecordBytes + 1]));
    }

    [Fact]
    public async Task ClosedWindowCanBeReadBeforeFinalization()
    {
        var writer = new MeasurementFileWriter(_root, Guid.NewGuid());
        var running = writer.RunAsync();
        writer.TryEnqueue(Encoding.UTF8.GetBytes("{}"));
        var until = DateTime.UtcNow.AddSeconds(5);
        string? file;
        while ((file = Directory.GetFiles(writer.DirectoryPath, "*.jsonl").FirstOrDefault()) is null || new FileInfo(file).Length < 3)
        {
            Assert.True(DateTime.UtcNow < until);
            await Task.Delay(10);
        }
        try
        {
            using var input = new FileStream(file, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
            using var reader = new StreamReader(input);
            Assert.Equal("{}\n", reader.ReadToEnd());
            Assert.False(running.IsCompleted);
        }
        finally { writer.Complete(); await running; }
    }

    [Fact]
    public async Task DiskErrorAndSessionLimitAreContained()
    {
        Directory.CreateDirectory(_root);
        var blocked = Path.Combine(_root, "file-instead-of-directory");
        File.WriteAllText(blocked, "fixture");
        var broken = new MeasurementFileWriter(blocked, Guid.NewGuid());
        broken.TryEnqueue(Encoding.UTF8.GetBytes("{}"));
        broken.Complete();
        await broken.RunAsync();
        Assert.True(broken.Failed);
        Assert.False(broken.TryEnqueue(Encoding.UTF8.GetBytes("{}")));
        var limited = new MeasurementFileWriter(_root, Guid.NewGuid(), sessionBytes: 4);
        limited.TryEnqueue(Encoding.UTF8.GetBytes("{}"));
        limited.TryEnqueue(Encoding.UTF8.GetBytes("{}"));
        limited.Complete();
        await limited.RunAsync();
        Assert.True(limited.Failed);
        Assert.Equal("{}\n", File.ReadAllText(Directory.GetFiles(limited.DirectoryPath, "*.jsonl").Single()));
    }

    [Fact]
    public async Task GracefulStopFlushesPartialAndMapsInstanceWithoutSecrets()
    {
        using var host = new MeasurementHost(new() { Enabled = true, SessionId = Guid.NewGuid(), OutputDirectory = _root }, "worker", "synthetic-worker");
        await host.StartAsync(default);
        PerformanceMetrics.Count(Event.TerminalApplied, Outcome.Sent, 7);
        await host.StopAsync(default).WaitAsync(TimeSpan.FromSeconds(5));
        var directory = Directory.GetDirectories(Path.Combine(_root, "processes")).Single();
        Assert.True(File.Exists(Path.Combine(directory, "stopped.json")));
        using var interval = JsonDocument.Parse(File.ReadAllText(Directory.GetFiles(directory, "intervals-*.jsonl").Single()));
        Assert.Equal("partial", interval.RootElement.GetProperty("quality").GetString());
        Assert.Equal(7, interval.RootElement.GetProperty("metrics").GetProperty("terminal.sent.delta").GetProperty("value").GetInt64());
    }

    public void Dispose()
    {
        if (Directory.Exists(_root)) Directory.Delete(_root, true);
    }
}

using System.Text.Json;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Hosting.Server;
using Microsoft.AspNetCore.Hosting.Server.Features;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using PackCall.Infrastructure.Hosting;
using PackCall.Infrastructure.Sending;

namespace PackCall.Core.Test;

public class OperatorHttpTests
{
    [Fact]
    public async Task SharedEmailFixturesMatchProductValidation()
    {
        using var fixture = JsonDocument.Parse(await File.ReadAllTextAsync(Path.Combine(AppContext.BaseDirectory,"email-fixtures.json")));
        var sender = new MockEmailSender(new OperatorRandom());
        foreach (var item in fixture.RootElement.EnumerateArray())
        {
            var value = item.GetProperty("value").GetString()!;
            var request = item.TryGetProperty("field", out var field) && field.GetString() == "message"
                ? TestOperatorTests.Request with { MessageText = value }
                : TestOperatorTests.Request with { RecipientEmail = value };
            if (item.GetProperty("valid").GetBoolean()) Assert.True((await sender.SendAsync(request, false, default)).IsSuccess);
            else await Assert.ThrowsAsync<TestOperatorValidationException>(() => sender.SendAsync(request, false, default));
        }
    }

    [Fact]
    public async Task ActualHttpPayloadContainsEveryBooleanAndParsesConfirmedResults()
    {
        var flags = new List<bool>();
        await using var server = await OperatorServer.Start(async context => {
            Assert.Equal("/v1/email/send", context.Request.Path);
            using var body = await JsonDocument.ParseAsync(context.Request.Body);
            flags.Add(body.RootElement.GetProperty("simulate_errors").GetBoolean());
            context.Response.ContentType = "application/json";
            await context.Response.WriteAsync(flags.Count % 2 == 0 ? "{\"result\":\"rejected\",\"code\":\"SimulatedOperatorRejected\"}" : "{\"result\":\"accepted\",\"code\":\"AcceptedByProvider\"}");
        });
        using var sender = server.Sender();
        foreach (var flag in new[]{ false, false, true, true }) await sender.SendAsync(TestOperatorTests.Request, flag, default);
        Assert.Equal(new[]{false,false,true,true}, flags);
    }

    [Theory]
    [InlineData(422, "{}", "application/json", typeof(TestOperatorValidationException))]
    [InlineData(415, "{}", "application/json", typeof(TestOperatorProtocolException))]
    [InlineData(500, "marker", "application/json", typeof(TestOperatorServiceException))]
    [InlineData(302, "", "application/json", typeof(TestOperatorProtocolException))]
    [InlineData(200, "bad marker", "application/json", typeof(TestOperatorProtocolException))]
    [InlineData(200, "{}", "application/json", typeof(TestOperatorProtocolException))]
    [InlineData(200, "{\"result\":\"accepted\",\"code\":\"SimulatedOperatorRejected\"}", "application/json", typeof(TestOperatorProtocolException))]
    [InlineData(200, "{\"result\":\"accepted\",\"code\":\"AcceptedByProvider\",\"extra\":1}", "application/json", typeof(TestOperatorProtocolException))]
    [InlineData(200, "{\"result\":\"accepted\",\"code\":\"AcceptedByProvider\"}", "text/plain", typeof(TestOperatorProtocolException))]
    public async Task ErrorsNeverBecomeConfirmedResults(int status, string body, string contentType, Type error)
    {
        await using var server = await OperatorServer.Start(async context => {
            context.Response.StatusCode = status; context.Response.ContentType = contentType;
            await context.Response.WriteAsync(body);
        });
        using var sender = server.Sender();
        foreach (var flag in new[]{false,true})
        {
            var ex = await Record.ExceptionAsync(() => sender.SendAsync(TestOperatorTests.Request, flag, default));
            Assert.IsType(error, ex); Assert.Null(ex!.InnerException); Assert.DoesNotContain("marker",ex.ToString());
        }
    }

    [Fact]
    public async Task ResponseLimitTimeoutAndExternalCancellation()
    {
        await using (var server = await OperatorServer.Start(c => c.Response.WriteAsync(new string('x',4097))))
        {
            using var sender = server.Sender();
            await Assert.ThrowsAsync<TestOperatorProtocolException>(() => sender.SendAsync(TestOperatorTests.Request,false,default));
        }
        await using (var server = await OperatorServer.Start(async c => {
            try { await Task.Delay(10000,c.RequestAborted); } catch(OperationCanceledException) { }
        }))
        {
            using var sender = server.Sender(.1);
            await Assert.ThrowsAsync<TestOperatorTimeoutException>(() => sender.SendAsync(TestOperatorTests.Request,false,default));
            using var ct = new CancellationTokenSource(20);
            var exception = await Assert.ThrowsAnyAsync<OperationCanceledException>(() => sender.SendAsync(TestOperatorTests.Request,false,ct.Token));
            Assert.Equal(ct.Token,exception.CancellationToken);
        }
    }

    [Fact]
    public async Task DisconnectAndConnectionRefusedAreTransportErrors()
    {
        Uri url;
        await using (var server = await OperatorServer.Start(c => { c.Abort(); return Task.CompletedTask; }))
        {
            url=server.Url;
            using var sender=server.Sender();
            await Assert.ThrowsAsync<TestOperatorTransportException>(() => sender.SendAsync(TestOperatorTests.Request,false,default));
        }
        using var refused=new HttpTestEmailSender(new(TestSenderMode.Http,false,url));
        await Assert.ThrowsAsync<TestOperatorTransportException>(() => refused.SendAsync(TestOperatorTests.Request,false,default));
    }
}

internal sealed class OperatorServer(WebApplication app, Uri url) : IAsyncDisposable
{
    public Uri Url => url;
    public HttpTestEmailSender Sender(double seconds=5) => new(new(TestSenderMode.Http,false,url,TimeSpan.FromSeconds(seconds)));
    public static async Task<OperatorServer> Start(RequestDelegate handler)
    {
        var builder=WebApplication.CreateBuilder();
        builder.Logging.ClearProviders(); builder.WebHost.UseUrls("http://127.0.0.1:0");
        var app=builder.Build(); app.Run(handler); await app.StartAsync();
        var url=app.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>()!.Addresses.Single();
        return new(app,new Uri(url));
    }
    private bool _disposed;
    public async ValueTask DisposeAsync() { if(_disposed)return; _disposed=true; await app.StopAsync(); await app.DisposeAsync(); }
}

