namespace PackCall.Core.Test;

public class WorkerLeaseBudgetTests
{
    [Theory]
    [InlineData("valid", true)]
    [InlineData("expired", false)]
    [InlineData("elapsed", false)]
    [InlineData("error", false)]
    public async Task Budget_UsesDatabaseClockAndElapsed_WithoutChangingBatchExpiry(string mode, bool expectedSend)
    {
        // Deliberately far from application UTC: local wall clock must not decide the budget.
        var dbNow = new DateTime(2040, 1, 1, 0, 0, 0, DateTimeKind.Utc);
        var processor = new Processor(dbNow.AddSeconds(mode == "expired" ? -1 : 10));
        var time = new ControlledTime();
        var clock = new Clock(() =>
        {
            if (mode == "error") throw new InvalidOperationException("clock unavailable");
            if (mode == "elapsed") time.Elapsed += TimeSpan.FromSeconds(10);
            return dbNow;
        });
        using var services = new ServiceCollection().AddSingleton<IDeliveryProcessingService>(processor)
            .AddSingleton<ILeaseClock>(clock).BuildServiceProvider();
        using var logger = new LoggerConfiguration().CreateLogger();
        using var worker = new DeliveryWorker(services.GetRequiredService<IServiceScopeFactory>(),
            Options.Create(new DeliveryWorkerOptions { Parallelism = 1, BatchSize = 2,
                LockDuration = TimeSpan.FromSeconds(10), IdleDelay = TimeSpan.FromMilliseconds(5),
                ErrorDelay = TimeSpan.FromMilliseconds(5), RecoveryInterval = TimeSpan.FromMilliseconds(5) }),
            logger, timeProvider: time);
        await worker.StartAsync(CancellationToken.None);
        try { await processor.NextCapture.Task.WaitAsync(TimeSpan.FromSeconds(5)); }
        finally { await worker.StopAsync(CancellationToken.None); }
        Assert.Equal(expectedSend ? 2 : 0, processor.Sent.Count);
        Assert.All(processor.Sent, d => Assert.Equal(processor.Expiry, d.LockExpiresAt));
        Assert.All(processor.Batch, d => Assert.Equal(DeliveryStatus.InProgress, d.DeliveryStatus));
    }

    [Fact]
    public async Task Budget_CancelsActiveProcessing_ThenContinuesLaneWithoutChangingLease()
    {
        var dbNow = new DateTime(2040, 1, 1, 0, 0, 0, DateTimeKind.Utc);
        // Valid ten-second options give a one-second safety margin, leaving 50ms.
        var processor = new Processor(dbNow.AddMilliseconds(1050));
        var nextProcessed = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var firstCancelled = false;
        processor.Handler = async (delivery, ct) =>
        {
            if (delivery.Id == processor.Batch[0].Id)
            {
                try { await Task.Delay(Timeout.InfiniteTimeSpan, ct); }
                catch (OperationCanceledException)
                {
                    firstCancelled = ct.IsCancellationRequested;
                    throw;
                }
            }
            else
            {
                Assert.False(ct.IsCancellationRequested);
                nextProcessed.TrySetResult();
            }
        };
        using var services = new ServiceCollection().AddSingleton<IDeliveryProcessingService>(processor)
            .AddSingleton<ILeaseClock>(new Clock(() => dbNow)).BuildServiceProvider();
        using var logger = new LoggerConfiguration().CreateLogger();
        using var worker = new DeliveryWorker(services.GetRequiredService<IServiceScopeFactory>(),
            Options.Create(new DeliveryWorkerOptions { Parallelism = 1, BatchSize = 2,
                LockDuration = TimeSpan.FromSeconds(10), IdleDelay = TimeSpan.FromMilliseconds(5),
                ErrorDelay = TimeSpan.FromMilliseconds(5), RecoveryInterval = TimeSpan.FromMilliseconds(5) }),
            logger, timeProvider: new ControlledTime());
        await worker.StartAsync(CancellationToken.None);
        try { await nextProcessed.Task.WaitAsync(TimeSpan.FromSeconds(5)); }
        finally { await worker.StopAsync(CancellationToken.None); }
        Assert.True(firstCancelled);
        Assert.Equal(processor.Batch.Select(d => d.Id), processor.Sent.Select(d => d.Id));
        Assert.All(processor.Batch, d =>
        {
            Assert.Equal(processor.Expiry, d.LockExpiresAt);
            Assert.Equal(DeliveryStatus.InProgress, d.DeliveryStatus);
            Assert.Null(d.CompletedAt);
        });
    }

    private sealed class ControlledTime : TimeProvider
    {
        public TimeSpan Elapsed;
        public override long TimestampFrequency => TimeSpan.TicksPerSecond;
        public override long GetTimestamp() => Elapsed.Ticks;
    }
    private sealed class Clock(Func<DateTime> read) : ILeaseClock
    {
        public Task<DateTime> GetUtcNowAsync(CancellationToken ct) => Task.FromResult(read());
    }
    private sealed class Processor(DateTime expiry) : IDeliveryProcessingService
    {
        private int _capture;
        public DateTime Expiry => expiry;
        public List<Delivery> Sent { get; } = [];
        public List<Delivery> Batch { get; } = [];
        public TaskCompletionSource NextCapture { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        public Task<IReadOnlyList<Delivery>> CaptureBatchAsync(int size, string owner, TimeSpan duration, CancellationToken ct)
        {
            if (Interlocked.Increment(ref _capture) > 1)
            {
                NextCapture.TrySetResult();
                return Task.FromResult<IReadOnlyList<Delivery>>([]);
            }
            for (var i = 0; i < 2; i++)
            {
                var d = Delivery.Create(Guid.NewGuid(), Guid.NewGuid(), "user@example.com", expiry.AddSeconds(-10));
                d.SetCapturedForTest(owner, expiry, expiry.AddSeconds(-10));
                Batch.Add(d);
            }
            return Task.FromResult<IReadOnlyList<Delivery>>(Batch);
        }
        public Func<Delivery, CancellationToken, Task>? Handler { get; set; }
        public Task ProcessAsync(Delivery delivery, CancellationToken ct)
        {
            Sent.Add(delivery);
            return Handler?.Invoke(delivery, ct) ?? Task.CompletedTask;
        }
        public Task<int> ReleaseExpiredLocksAsync(CancellationToken ct) => Task.FromResult(0);
        public Task<bool> CompleteCampaignIfFinishedAsync(Guid id, CancellationToken ct) => Task.FromResult(false);
    }
}

using System.Reflection;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Options;
using PackCall.Core.Diagnostics;
using PackCall.Core.Entities;
using PackCall.Core.Services;
using PackCall.Worker.Background;
using Serilog;

namespace PackCall.Core.Test;

[Collection("Measurement")]
public sealed class WorkerMeasurementTests
{
    [Fact]
    public async Task BatchWaitIncludesCaptureJournalAndPreviousRowsButNotWallClockJump()
    {
        using var collector = new MeasurementCollector(new() { Enabled = true, SessionId = Guid.NewGuid(), OutputDirectory = "unused" });
        var clock = new Clock();
        using var services = new ServiceCollection().BuildServiceProvider();
        using var logger = new LoggerConfiguration().CreateLogger();
        using var worker = new DeliveryWorker(services.GetRequiredService<IServiceScopeFactory>(),
            Options.Create(new DeliveryWorkerOptions()), logger, new WorkerIdentity("worker"), clock);
        var rows = Enumerable.Range(0, 3).Select(_ => Delivery.Create(Guid.NewGuid(), Guid.NewGuid(), "synthetic@example.invalid", DateTime.UtcNow)).ToArray();
        foreach (var row in rows) row.SetCapturedForTest("worker", DateTime.UtcNow.AddMinutes(1));
        CaptureTiming.Record(rows, clock);
        clock.Ticks += 100; // capture journal
        var processor = new Processor(clock);
        foreach (var row in rows) await Invoke(worker, processor, new LeaseClock(), row);
        var window = collector.Close()!;
        var wait = window.Histograms[new((int)Operation.BatchWait, Outcome.Success, Purpose.None)];
        Assert.Equal(100, wait.Min);
        Assert.Equal(500, wait.Max);
        Assert.Equal(900, wait.Sum);
        Assert.Equal(3, wait.Count);
        var processing = window.Histograms[new((int)Operation.ProcessingTotal, Outcome.TerminalPathComplete, Purpose.None)];
        Assert.Equal(600, processing.Sum);
        Assert.Equal(3, processor.Calls);
    }

    [Theory]
    [InlineData(false)] [InlineData(true)]
    public async Task LeaseSkipOrInvalidOwnerDoesNotCallService(bool invalidOwner)
    {
        using var collector = new MeasurementCollector(new() { Enabled = true, SessionId = Guid.NewGuid(), OutputDirectory = "unused" });
        var clock = new Clock();
        using var services = new ServiceCollection().BuildServiceProvider();
        using var logger = new LoggerConfiguration().CreateLogger();
        using var worker = new DeliveryWorker(services.GetRequiredService<IServiceScopeFactory>(),
            Options.Create(new DeliveryWorkerOptions()), logger, new WorkerIdentity("worker"), clock);
        var row = Delivery.Create(Guid.NewGuid(), Guid.NewGuid(), "synthetic@example.invalid", DateTime.UtcNow);
        row.SetCapturedForTest(invalidOwner ? "other" : "worker", DateTime.UtcNow.AddMinutes(-1));
        var processor = new Processor(clock);
        await Invoke(worker, processor, new LeaseClock(), row);
        Assert.Equal(0, processor.Calls);
        var window = collector.Close()!;
        Assert.Equal(1, window.Counters[new((int)Event.ProcessingFinished, invalidOwner ? Outcome.InvalidCapture : Outcome.LeaseSkipped, Purpose.None)].Delta);
    }

    private static Task Invoke(DeliveryWorker worker, IDeliveryProcessingService processor, ILeaseClock clock, Delivery row) =>
        (Task)typeof(DeliveryWorker).GetMethod("ProcessCapturedAsync", BindingFlags.NonPublic | BindingFlags.Instance)!
            .Invoke(worker, [processor, clock, row, CancellationToken.None])!;

    [Theory]
    [InlineData(false)] [InlineData(true)]
    public async Task HostAndLeaseCancellationAreDistinct(bool host)
    {
        using var collector = new MeasurementCollector(new() { Enabled = true, SessionId = Guid.NewGuid(), OutputDirectory = "unused" });
        var clock = new Clock();
        using var services = new ServiceCollection().BuildServiceProvider();
        using var logger = new LoggerConfiguration().CreateLogger();
        using var worker = new DeliveryWorker(services.GetRequiredService<IServiceScopeFactory>(),
            Options.Create(new DeliveryWorkerOptions()), logger, new WorkerIdentity("worker"), clock);
        var row = Delivery.Create(Guid.NewGuid(), Guid.NewGuid(), "synthetic@example.invalid", DateTime.UtcNow);
        row.SetCapturedForTest("worker", DateTime.UtcNow.AddSeconds(5.2));
        using var cancellation = new CancellationTokenSource();
        if (host) cancellation.Cancel();
        var processor = new Processor(clock) { WaitForCancellation = true };
        var task = (Task)typeof(DeliveryWorker).GetMethod("ProcessCapturedAsync", BindingFlags.NonPublic | BindingFlags.Instance)!
            .Invoke(worker, [processor, new LeaseClock(), row, cancellation.Token])!;
        if (host) await Assert.ThrowsAsync<OperationCanceledException>(() => task);
        else await task.WaitAsync(TimeSpan.FromSeconds(5));
        var window = collector.Close()!;
        Assert.Equal(1, window.Counters[new((int)Event.Cancellation, host ? Outcome.Host : Outcome.Lease, Purpose.None)].Delta);
    }

    private sealed class Clock : TimeProvider
    {
        public long Ticks;
        public override long TimestampFrequency => 1000;
        public override long GetTimestamp() => Ticks;
        public override DateTimeOffset GetUtcNow() => DateTimeOffset.UnixEpoch.AddHours(Ticks);
    }
    private sealed class LeaseClock : ILeaseClock
    {
        public Task<DateTime> GetUtcNowAsync(CancellationToken ct) => Task.FromResult(DateTime.UtcNow);
    }
    private sealed class Processor(Clock clock) : IDeliveryProcessingService
    {
        public int Calls;
        public bool WaitForCancellation;
        public Task ProcessAsync(Delivery delivery, CancellationToken ct)
        {
            Calls++;
            if (WaitForCancellation) return Task.Delay(Timeout.InfiniteTimeSpan, ct);
            clock.Ticks += 200;
            if (ProcessingObservation.Current is { } observation) observation.Outcome = Outcome.TerminalPathComplete;
            return Task.CompletedTask;
        }
        public Task<IReadOnlyList<Delivery>> CaptureBatchAsync(int batchSize, string workerId, TimeSpan lockDuration, CancellationToken ct) => throw new NotSupportedException();
        public Task<int> ReleaseExpiredLocksAsync(CancellationToken ct) => throw new NotSupportedException();
        public Task<bool> CompleteCampaignIfFinishedAsync(Guid campaignId, CancellationToken ct) => throw new NotSupportedException();
    }
}

using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Npgsql;
using PackCall.Core.Repositorys;
using PackCall.Infrastructure;
using PackCall.Infrastructure.Hosting;
using Serilog;

namespace PackCall.Core.Test;

public partial class CampaignPausePostgresTests
{
    [PostgresFact]
    public async Task Capture_UsesOneDatabaseTimestamp_RecoveryPreservesLeaseReplacedWhileWaiting()
    {
        await CreateStartedCampaignAsync(2);
        await using var scope = _provider!.CreateAsyncScope();
        var repository = scope.ServiceProvider.GetRequiredService<IDeliveryRepository>();
        var context = scope.ServiceProvider.GetRequiredService<AppDbContext>();
        await context.Database.OpenConnectionAsync();
        var capturePid = ((NpgsqlConnection)context.Database.GetDbConnection()).ProcessID;
        await using var captureBlocker = new NpgsqlConnection(_connectionString);
        await captureBlocker.OpenAsync();
        await using var captureTransaction = await captureBlocker.BeginTransactionAsync();
        await using (var tableLock = new NpgsqlCommand("LOCK TABLE deliveries IN ACCESS EXCLUSIVE MODE", captureBlocker, captureTransaction))
            await tableLock.ExecuteNonQueryAsync();
        var capture = repository.CaptureBatchAsync(2, "old", TimeSpan.FromSeconds(60), CancellationToken.None);
        await WaitBlocked(capturePid);
        var before = await DatabaseNow();
        await captureTransaction.CommitAsync();
        var batch = await capture.WaitAsync(Timeout);
        var after = await DatabaseNow();
        Assert.Equal(2, batch.Count);
        Assert.Single(batch.Select(d => d.LockExpiresAt).Distinct());
        Assert.All(batch, d => {
            Assert.InRange(d.UpdatedAt, before, after);
            Assert.Equal(d.UpdatedAt.AddSeconds(60), d.LockExpiresAt);
        });
        Assert.Empty(await repository.ReleaseExpiredLocksAsync(CancellationToken.None));
        await context.Database.ExecuteSqlRawAsync("UPDATE deliveries SET lock_expires_at = clock_timestamp() - interval '1 second'");
        await context.Database.OpenConnectionAsync();
        var pid = ((NpgsqlConnection)context.Database.GetDbConnection()).ProcessID;
        await using var blocker = new NpgsqlConnection(_connectionString);
        await blocker.OpenAsync();
        await using var transaction = await blocker.BeginTransactionAsync();
        await using (var locked = new NpgsqlCommand("SELECT id FROM deliveries ORDER BY id FOR UPDATE", blocker, transaction))
            await locked.ExecuteNonQueryAsync();
        var recovery = repository.ReleaseExpiredLocksAsync(CancellationToken.None);
        await WaitBlocked(pid);
        await using (var renewed = new NpgsqlCommand("UPDATE deliveries SET worker_id='new', lock_expires_at=clock_timestamp()+interval '60 seconds'", blocker, transaction))
            await renewed.ExecuteNonQueryAsync();
        await transaction.CommitAsync();
        Assert.Empty(await recovery.WaitAsync(Timeout));
        var rows = await context.Deliveries.AsNoTracking().ToListAsync();
        Assert.All(rows, d => Assert.Equal("new", d.WorkerId));
    }

    [PostgresFact]
    public async Task SchemaGate_WaitsForExactHistory_RejectsUnknown_ObservesCancellation()
    {
        var factory = _provider!.GetRequiredService<IDbContextFactory<AppDbContext>>();
        using var logger = new LoggerConfiguration().CreateLogger();
        var lifetime = new Lifetime();
        var gate = new SchemaGate(factory, lifetime, logger);
        using var deadline = new CancellationTokenSource(Timeout);
        var waiting = gate.StartingAsync(deadline.Token);
        Assert.False(waiting.IsCompleted);
        await using var db = await factory.CreateDbContextAsync();
        await db.Database.ExecuteSqlRawAsync("CREATE TABLE \"__EFMigrationsHistory\" (\"MigrationId\" varchar(150) PRIMARY KEY, \"ProductVersion\" varchar(32) NOT NULL)");
        foreach (var id in db.Database.GetMigrations())
            await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO \"__EFMigrationsHistory\" VALUES ({id}, '10.0.4')");
        await waiting.WaitAsync(Timeout);
        await db.Database.ExecuteSqlRawAsync("INSERT INTO \"__EFMigrationsHistory\" VALUES ('20990101000000_Unknown','10.0.4')");
        await Assert.ThrowsAsync<InvalidOperationException>(() => gate.StartingAsync(deadline.Token));
        await db.Database.ExecuteSqlRawAsync("TRUNCATE \"__EFMigrationsHistory\"");
        var cancelled = gate.StartingAsync(deadline.Token);
        lifetime.StopApplication();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => cancelled);
    }

    private sealed class Lifetime : IHostApplicationLifetime
    {
        private readonly CancellationTokenSource _stop = new();
        public CancellationToken ApplicationStarted => CancellationToken.None;
        public CancellationToken ApplicationStopping => _stop.Token;
        public CancellationToken ApplicationStopped => CancellationToken.None;
        public void StopApplication() => _stop.Cancel();
    }
}

